import sys
from pysat.solvers import Glucose3

n = 15
solver = Glucose3()

def var(i, j):
    if i > j:
        i, j = j, i
    return i * n + j + 1

# Triangle-free
for i in range(n):
    for j in range(i + 1, n):
        for k in range(j + 1, n):
            solver.add_clause([-var(i, j), -var(j, k), -var(i, k)])

# Maximal: if not edge(i, j), they share a neighbor
# For each pair (i, j), we can introduce auxiliary variables or just write the clauses.
# Actually, x_{i,j} or (x_{i,k} and x_{j,k}) for some k.
# This means x_{i,j} or OR_k (x_{i,k} and x_{j,k}).
# Let y_{i,j,k} = x_{i,k} and x_{j,k}.
# y_{i,j,k} -> x_{i,k}
# y_{i,j,k} -> x_{j,k}
# x_{i,k} and x_{j,k} -> y_{i,j,k}
# Then x_{i,j} or OR_k y_{i,j,k}

aux_var_counter = n * n + 1

for i in range(n):
    for j in range(i + 1, n):
        clause = [var(i, j)]
        for k in range(n):
            if k == i or k == j:
                continue
            y = aux_var_counter
            aux_var_counter += 1
            # y -> x_{i,k}
            solver.add_clause([-y, var(i, k)])
            # y -> x_{j,k}
            solver.add_clause([-y, var(j, k)])
            # x_{i,k} and x_{j,k} -> y
            solver.add_clause([-var(i, k), -var(j, k), y])
            clause.append(y)
        solver.add_clause(clause)

# Fixed edges
fixed_edges = [(2,14), (6,13), (7,13), (10,13), (6,14)]
for u, v in fixed_edges:
    solver.add_clause([var(u, v)])

if solver.solve():
    model = solver.get_model()
    edges = []
    for i in range(n):
        for j in range(i + 1, n):
            if model[var(i, j) - 1] > 0:
                edges.append((i, j))
    print("SAT")
    print(edges)
else:
    print("UNSAT")
